import numpy as np
from collections import deque

def generate(params, n, chip):
    levels = int(params['levels'])
    trunk_len = int(params['trunk_len'])
    trunk_w = max(2, int(params['trunk_w']))
    branch_len = int(params['branch_len'])
    branch_w = max(2, int(params['branch_w']))
    twig_len = int(params['twig_len'])
    twig_w = max(2, int(params['twig_w']))

    grid = np.zeros((n, n), dtype=bool)
    ci0, ci1, cj0, cj1 = chip
    chip_cells = [(i, j) for i in range(ci0, ci1+1) for j in range(cj0, cj1+1)]
    for i, j in chip_cells:
        if 0 <= i < n and 0 <= j < n:
            grid[i, j] = True

    def add_rectangle(i_start, i_end, j_start, j_end):
        i_start = max(0, min(i_start, n))
        i_end = max(0, min(i_end, n))
        j_start = max(0, min(j_start, n))
        j_end = max(0, min(j_end, n))
        if i_start < i_end and j_start < j_end:
            grid[i_start:i_end, j_start:j_end] = True

    # Trunk: vertical above chip
    trunk_i0 = ci0 - trunk_len
    trunk_i1 = ci0
    trunk_j0 = (cj0 + cj1 - trunk_w) // 2
    trunk_j1 = trunk_j0 + trunk_w
    add_rectangle(trunk_i0, trunk_i1, trunk_j0, trunk_j1)

    # Connect trunk to chip vertically
    connect_i0 = ci0
    connect_i1 = ci0 + 1
    connect_j0 = max(cj0, trunk_j0)
    connect_j1 = min(cj1, trunk_j1) + 1
    if connect_i0 < connect_i1 and connect_j0 < connect_j1:
        add_rectangle(connect_i0, connect_i1, connect_j0, connect_j1)

    # Branches: left and right of trunk at base
    base_i = ci0
    for side in [-1, 1]:
        bj0 = trunk_j0 + side * trunk_w
        bj1 = bj0 + side * branch_w
        bi0 = base_i - branch_len
        bi1 = base_i
        if side == -1:
            bj0, bj1 = bj1, bj0  # ensure bj0 < bj1
        add_rectangle(bi0, bi1, min(bj0, bj1), max(bj0, bj1))

        # Twigs: left and right of each branch
        for t_side in [-1, 1]:
            tj0 = bj0 + t_side * branch_w
            tj1 = tj0 + t_side * twig_w
            ti0 = bi0 - twig_len
            ti1 = bi0
            if t_side == -1:
                tj0, tj1 = tj1, tj0
            add_rectangle(ti0, ti1, min(tj0, tj1), max(tj0, tj1))

    # Ensure connectivity via flood fill from chip
    visited = np.zeros_like(grid, dtype=bool)
    queue = deque()
    for i, j in chip_cells:
        if 0 <= i < n and 0 <= j < n:
            visited[i, j] = True
            queue.append((i, j))
    while queue:
        i, j = queue.popleft()
        for di, dj in [(-1,0),(1,0),(0,-1),(0,1)]:
            ni, nj = i + di, j + dj
            if 0 <= ni < n and 0 <= nj < n and grid[ni, nj] and not visited[ni, nj]:
                visited[ni, nj] = True
                queue.append((ni, nj))
    grid &= visited  # Keep only connected component

    # Enforce minimum feature size: dilate then erode with 2x2 kernel
    def morph_op(g, op):
        if op == 'dilate':
            h = np.zeros_like(g)
            for i in range(n):
                for j in range(n):
                    if g[i, j]:
                        for di in range(2):
                            for dj in range(2):
                                ni, nj = i + di, j + dj
                                if 0 <= ni < n and 0 <= nj < n:
                                    h[ni, nj] = True
            return h
        elif op == 'erode':
            h = np.zeros_like(g)
            for i in range(n):
                for j in range(n):
                    if g[i, j]:
                        ok = True
                        for di in range(2):
                            for dj in range(2):
                                ni, nj = i + di, j + dj
                                if not (0 <= ni < n and 0 <= nj < n and g[ni, nj]):
                                    ok = False
                                    break
                            if not ok:
                                break
                        if ok:
                            h[i, j] = True
            return h
        return g

    grid = morph_op(grid, 'dilate')
    grid = morph_op(grid, 'erode')

    # Final connectivity check
    visited = np.zeros_like(grid, dtype=bool)
    queue = deque()
    start_found = False
    for i, j in chip_cells:
        if 0 <= i < n and 0 <= j < n and grid[i, j]:
            visited[i, j] = True
            queue.append((i, j))
            start_found = True
            break
    if start_found:
        while queue:
            i, j = queue.popleft()
            for di, dj in [(-1,0),(1,0),(0,-1),(0,1)]:
                ni, nj = i + di, j + dj
                if 0 <= ni < n and 0 <= nj < n and grid[ni, nj] and not visited[ni, nj]:
                    visited[ni, nj] = True
                    queue.append((ni, nj))
        grid &= visited

    # Enforce cell budget
    if np.sum(grid) > 1440:
        coords = np.argwhere(grid)
        if len(coords) > 1440:
            coords = coords[:1440]
        grid = np.zeros_like(grid)
        for i, j in coords:
            grid[i, j] = True

    return grid

